def os_open(document):
    """Open document by the default handler of the OS, could be a url opened by a browser, a text file by an editor etc"""
    osname = platform.system().lower()
    if osname == "darwin":
        os.system("open \"" + document + "\"")
    if osname == "linux":
        cmd = "xdg-open \"" + document + "\"&"
        os.system(cmd)
    if osname == "windows":
        os.system("start \"" + document + "\"")

def _load_job(self):
        """
        If there is still a job in the job iterator, loads it and increments
        the active job count.
        """

        try:
            next_job = next(self._jobs)
        except StopIteration:
            self._on_deck = None
        else:
            if not isinstance(next_job, Job):
                next_job = DefaultJob(next_job)
            self._on_deck = next_job
            self._active_jobs += 1

def iterate_pages(self):
        """Iterate Pages.

        A generator which iterates over all pages.
        Keep in mind that Amazon limits the number of pages it makes available.

        :return:
            Yields lxml root elements.
        """
        try:
            while True:
                yield self._query(ItemPage=self.current_page, **self.kwargs)
                self.current_page += 1
        except NoMorePages:
            pass

def count_bytes(self, filter_preds):
        '''Count bytes of all feature collections whose key satisfies one of
        the predicates in ``filter_preds``. The byte counts are binned
        by filter predicate.
        '''
        num_bytes = defaultdict(int)
        for hit in self._scan():
            for filter_pred in filter_preds:
                if filter_pred(did(hit['_id'])):
                    num_bytes[filter_pred] += self.fc_bytes(
                        hit['_source']['fc'])
        return num_bytes

def _getAssociatedClk(self):
        """
        If interface has associated clk return it otherwise
        try to find clk on parent recursively
        """
        a = self._associatedClk

        if a is not None:
            return a

        p = self._parent
        assert p is not None

        if isinstance(p, UnitBase):
            return getClk(p)
        else:
            return p._getAssociatedClk()

