		"Hard-code the styles into the SVG XML if style sheets are not used."
		if not self.css_inline:
			# do nothing
			return

		styles = self.parse_css()
		for node in self.root.xpath('//*[@class]'):
			cl = '.' + node.attrib['class']
			if cl not in styles:
